using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using NexHire.Domain.Entities;namespace NexHire.Infrastructure.Data.Configurations;public sealed class RefreshTokenConfiguration:IEntityTypeConfiguration<RefreshToken>{public void Configure(EntityTypeBuilder<RefreshToken>b){b.ToTable("RefreshTokens");b.HasKey(x=>x.Id);b.Property(x=>x.TokenHash).HasMaxLength(64).IsRequired();b.HasIndex(x=>x.TokenHash).IsUnique();}}
